#[derive(Debug, Clone)]
pub enum PageChannelEvent {
    BindingCall(PageBindingCallEventParams),
    Close,
    Crash,
    Download(PageDownloadEventParams),
    ViewportSizeChanged(PageViewportSizeChangedEventParams),
    FileChooser(PageFileChooserEventParams),
    FrameAttached(PageFrameAttachedEventParams),
    FrameDetached(PageFrameDetachedEventParams),
    LocatorHandlerTriggered(PageLocatorHandlerTriggeredEventParams),
    Route(PageRouteEventParams),
    ScreencastFrame(PageScreencastFrameEventParams),
    WebSocketRoute(PageWebSocketRouteEventParams),
    WebSocket(PageWebSocketEventParams),
    Worker(PageWorkerEventParams),
    Unknown { method: String, params: serde_json::Value },
}

impl PageChannelEvent {
    pub fn parse(method: &str, params: serde_json::Value) -> PageChannelEvent {
        match method {
            "bindingCall" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::BindingCall(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "close" => PageChannelEvent::Close,
            "crash" => PageChannelEvent::Crash,
            "download" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::Download(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "viewportSizeChanged" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::ViewportSizeChanged(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "fileChooser" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::FileChooser(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "frameAttached" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::FrameAttached(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "frameDetached" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::FrameDetached(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "locatorHandlerTriggered" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::LocatorHandlerTriggered(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "route" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::Route(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "screencastFrame" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::ScreencastFrame(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "webSocketRoute" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::WebSocketRoute(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "webSocket" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::WebSocket(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            "worker" => match serde_json::from_value(params.clone()) { Ok(p) => PageChannelEvent::Worker(p), Err(_) => PageChannelEvent::Unknown { method: method.to_string(), params } },
            _ => PageChannelEvent::Unknown { method: method.to_string(), params },
        }
    }
}

